31	template <typename T> constexpr __aicore__ inline void CheckCreateVecIndexApi0SupportedType()
32	{
33	    static_assert(SupportType<T, int16_t, int32_t, half, float>(),
34	        "CreateVecIndex level-0 api only support int16_t/int32_t/half/float on current device");
35	}
36	
37	template <typename T> constexpr __aicore__ inline void CheckCreateVecIndexApi2SupportedType()
38	{
39	    static_assert(SupportType<T, int8_t, int16_t, int32_t, half, float, int64_t>(),
40	        "CreateVecIndex level-2 api only support int8_t/int16_t/int32_t/half/float/int64_t on current device");
41	}
