43	namespace Internal {
44	template <bool isMaskBitMode, bool isNormalMode, typename T>
45	__simd_vf__ inline void VecCreateVecIndexLevel0VFImpl(__ubuf__ T *dst, const T firstValue, const BasicAPIMaskStruct maskArrayStruct,
46	    const uint64_t maskCount, const uint8_t repeatTime, uint16_t dstBlkStride, uint8_t dstRepStride,
47	    __ubuf__ uint64_t *maskBuf)
48	{
49	    constexpr uint32_t sreg = GetVecLen() / sizeof(T);
50	    uint32_t count = VecMicroGetCount<true, isNormalMode, isMaskBitMode>(maskArrayStruct.maskArray, maskCount, maskBuf);
51	    uint16_t newRepeatTimes = VecMicroGetRepeatTimes<T, isNormalMode>(count, repeatTime);
52	    Reg::MaskReg maskReg;
53	    if constexpr (isNormalMode) {
54	        maskReg = VecMicroGetMaskReg<T, true, isNormalMode, isMaskBitMode>(maskBuf, count);
55	    }
56	    constexpr uint8_t ElePerBlkT = GetDataBlockSizeInBytes() / sizeof(T);
57	    Reg::RegTensor<T> dstVreg;
58	    Reg::Arange(dstVreg, firstValue);
59	    for (uint16_t index = 0; index < newRepeatTimes; ++index) {
60	        if constexpr (!isNormalMode) {
61	            maskReg = VecMicroGetMaskReg<T, true, isNormalMode, isMaskBitMode>(maskBuf, count);
62	        }
63	        Reg::StoreAlign<T, Reg::DataCopyMode::DATA_BLOCK_COPY>(
64	            dst + index * dstRepStride * ElePerBlkT, dstVreg, dstBlkStride, maskReg);
65	        Reg::Adds(dstVreg, dstVreg, sreg, maskReg);
66	    }
67	}
68	 
69	template <bool isMaskBitMode, typename T>
70	__aicore__ inline void VecCreateVecIndexLevel0Template(__ubuf__ T *dst, const T firstValue, const uint64_t maskArray[],
71	    const uint64_t maskCount, const uint8_t repeatTime, uint16_t dstBlkStride, uint8_t dstRepStride)
72	{
73	    BasicAPIMaskStruct maskArrayStruct;
74	    if constexpr (isMaskBitMode) {
75	        ASCENDC_ASSERT(maskCount == 0, "maskCount must be 0 when isMaskBitMode is true.");
76	        maskArrayStruct = *(reinterpret_cast<const BasicAPIMaskStruct*>(maskArray));
77	    } else {
78	        ASCENDC_ASSERT(maskArray == nullptr, "maskArray must be nullptr when isMaskBitMode is false.");
79	    }
80	
81	    if (Internal::IsCounterMode()) {
82	        VecCreateVecIndexLevel0VFImpl<isMaskBitMode, false, T>(dst, firstValue, maskArrayStruct, maskCount,
83	            repeatTime, dstBlkStride, dstRepStride, nullptr);
84	    } else {
85	        if constexpr (isMaskBitMode) {
86	            SetVectorMask<T>(maskArray[1], maskArray[0]); // set mask to SPR.MASK, movp in VF
87	        }
88	        VecCreateVecIndexLevel0VFImpl<isMaskBitMode, true, T>(dst, firstValue, maskArrayStruct, maskCount,
89	            repeatTime, dstBlkStride, dstRepStride, nullptr);
90	    }
91	}
92	} // namespace Internal
