94	// VCI level-0 normal
95	template <typename T>
96	__aicore__ inline void CreateVecIndexCalc(LocalTensor<T> &dstLocal, const T firstValue, uint64_t mask,
97	    uint8_t repeatTime, uint16_t dstBlkStride, uint8_t dstRepStride)
98	{
99	    CheckCreateVecIndexApi0SupportedType<T>();
100	
101	    __ubuf__ T* dst = (__ubuf__ T*)dstLocal.GetPhyAddr();
102	    Internal::VecCreateVecIndexLevel0Template<false>(dst, firstValue, nullptr, mask, repeatTime, dstBlkStride, dstRepStride);
103	}
