105	// VCI level-0 bitwise
106	template <typename T>
107	__aicore__ inline void CreateVecIndexCalc(LocalTensor<T> &dstLocal, const T firstValue,
108	    uint64_t mask[], uint8_t repeatTime, uint16_t dstBlkStride, uint8_t dstRepStride)
109	{
110	    CheckCreateVecIndexApi0SupportedType<T>();
111	
112	    __ubuf__ T* dst = (__ubuf__ T*)dstLocal.GetPhyAddr();
113	    Internal::VecCreateVecIndexLevel0Template<true>(dst, firstValue, mask, 0, repeatTime, dstBlkStride, dstRepStride);
114	}
