116	template <typename T>
117	__simd_vf__ inline void CreateVecIndexCalcVci2(__ubuf__ T* dstLocalAddr, const T firstValue,
118	    uint32_t sreg, uint32_t sregLower, uint16_t repeatTime)
119	{
120	    Reg::RegTensor<T> vreg0;
121	    Reg::MaskReg preg;
122	    Reg::Arange(vreg0, firstValue);
123	    for (uint16_t i = 0; i < (uint16_t)repeatTime; ++i) {
124	        preg = Reg::UpdateMask<T>(sreg);
125	        Reg::StoreAlign(dstLocalAddr + i * sregLower, vreg0, preg);
126	        Reg::Adds(vreg0, vreg0, sregLower, preg);
127	    }
128	}
129	
130	// VCI level-2
131	template <typename T>
132	__aicore__ inline void CreateVecIndexCalc(LocalTensor<T> dstLocal, const T firstValue, uint32_t calCount)
133	{
134	    CheckCreateVecIndexApi2SupportedType<T>();
135	
136	    __ubuf__ T* dstLocalAddr = (__ubuf__ T*)dstLocal.GetPhyAddr();
137	    uint32_t sreg = static_cast<uint32_t>(calCount);
138	    uint32_t sregLower = static_cast<uint32_t>(GetVecLen() / sizeof(T));
139	    uint16_t repeatTime = CeilDivision(calCount, sregLower);
140	    CreateVecIndexCalcVci2<T>(dstLocalAddr, firstValue, sreg, sregLower, repeatTime);
141	}
142	
143	template <typename T = int64_t>
144	__simd_vf__ inline void CreateVecIndexCalcVic(__ubuf__ int64_t* dstLocalAddr, const int64_t firstValue, uint32_t calCount) {
145	    Reg::RegTensor<int64_t, Reg::RegTraitNumTwo> vreg0;
146	    uint32_t sreg = static_cast<uint32_t>(calCount);
147	    Reg::MaskReg preg;
148	    constexpr uint16_t sregLower = SupportBytes<T, 8>() ? GetVecLen() / sizeof(float) : GetVecLen() / sizeof(T);
149	    uint16_t repeatTime = CeilDivision(calCount, sregLower);
150	    for (uint16_t i = 0; i < repeatTime; ++i) {
151	        preg = Reg::UpdateMask<int64_t, Reg::RegTraitNumTwo>(sreg);
152	        int64_t offset = static_cast<int64_t>(firstValue + i * sregLower);
153	        Reg::Arange(vreg0, offset);
154	        Reg::StoreAlign(dstLocalAddr + i * sregLower, vreg0, preg);
155	    }
156	}
157	
158	template <typename T = int64_t>
159	__aicore__ inline void CreateVecIndexCalc(LocalTensor<int64_t> dstLocal, const int64_t firstValue, uint32_t calCount) {
160	    __ubuf__ int64_t* dstLocalAddr = (__ubuf__ int64_t*)dstLocal.GetPhyAddr();
161	    CreateVecIndexCalcVic<T>(dstLocalAddr, firstValue, calCount);
162	}
