24	// Helper: CopyOut (UB → GM) - needs 3 args
25	template <typename T>
26	__aicore__ inline void CopyOutHelper(const AscendC::GlobalTensor<T> &dst, AscendC::LocalTensor<T> &src, uint32_t count)
27	{
28	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
29	    AscendC::DataCopyPad(dst, src, copyParams);
30	}
