20	// dtypeFlag: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64
21	static int64_t GetDtypeFlag(at::ScalarType dtype)
22	{
23	    switch (dtype) {
24	        case at::kHalf:     return 0;
25	        case at::kBFloat16: return 1;
26	        case at::kFloat:    return 2;
27	        case at::kInt:      return 3;
28	        case at::kLong:     return 4;
29	        default:            return -1;
30	    }
31	}
32	
33	// bufferCoefficient: per-element UB usage in bytes, derived from UB allocation table
34	static int64_t GetBufferCoefficient(int64_t dtypeFlag)
35	{
36	    // float16/bf16:  16  (inQueue*2*2 + outQueue*2*2 + tempBufX*4 + tempBufY*4 = 16 per elem)
37	    // float32:       16  (inQueue*2*4 + outQueue*2*4 = 16 per elem, no TBuf needed)
38	    // int32:         24  (inQueue*2*4 + outQueue*2*4 + tempBufX*4 + tempBufY*4 = 24, int→fp32 cast path)
39	    // int64:         40  (inQueue*2*8 + outQueue*2*8 + tempBufX*4 + tempBufY*4 = 40, int→fp32 cast path)
40	    switch (dtypeFlag) {
41	        case 0: case 1: return 16;   // float16 / bfloat16
42	        case 2:         return 16;   // float32
43	        case 3:         return 24;   // int32 (cast path)
44	        case 4:         return 40;   // int64 (cast path)
45	        default:        return 16;
46	    }
47	}
48	
49	at::Tensor abs_math(const at::Tensor &self)
50	{
51	    // ---- 输入校验 ----
52	    TORCH_CHECK(self.is_contiguous(), "abs_math: input must be contiguous");
53	
54	    int64_t dtypeFlag = GetDtypeFlag(self.scalar_type());
55	    TORCH_CHECK(dtypeFlag >= 0, "abs_math: unsupported dtype, got ", self.scalar_type());
56	
57	    at::Tensor output = at::empty_like(self);
58	
59	    int64_t totalLength = self.numel();
60	    if (totalLength == 0) {
61	        return output;
62	    }
63	
64	    int64_t dtypeSize = self.element_size();
65	
66	    // ---- 获取硬件参数 ----
67	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
68	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
69	    uint64_t ubSize;
70	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
71	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
72	
73	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
74	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
75	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
76	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
77	
78	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
79	    int64_t formerNum = usedCoreNum - 1;
80	    int64_t formerLength = totalLengthCoreAlign;
81	    int64_t tailLength = totalLength - formerNum * formerLength;
82	
83	    // ---- UB 级 tiling (核内切分) ----
84	    int64_t bufferCoefficient = GetBufferCoefficient(dtypeFlag);
85	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
86	    if (dtypeSize == 0) { dtypeSize = 1; }
87	    int64_t alignElements = 32 / dtypeSize;
88	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
89	
90	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
91	
92	    EXEC_KERNEL_CMD(abs_math, blockDim,
93	                    self, output,
94	                    formerNum, formerLength, tailLength, tileLength,
95	                    dtypeSize, dtypeFlag);
96	
97	    return output;
98	}
