#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_arange.h"
#include <cmath>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t SYSTEM_WORKSPACE_SIZE = 16 * 1024 * 1024;  // 16MB

// dtypeFlag: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64
static int64_t GetDtypeFlag(at::ScalarType dtype)
{
    switch (dtype) {
        case at::kHalf:     return 0;
        case at::kBFloat16: return 1;
        case at::kFloat:    return 2;
        case at::kInt:      return 3;
        case at::kLong:     return 4;
        default:            return -1;
    }
}

// bufferCoefficient: per-element UB usage in bytes
// float16/bf16: 8  (outQueue*2*2 + tempBuf*4 = 8 per elem)
// float32:      12 (outQueue*2*4 + tempBuf*4 = 12 per elem)
// int32:        12 (outQueue*2*4 + tempBuf*4 = 12 per elem)
// int64:        24 (outQueue*2*8 + tempBuf*8 = 24 per elem)
static int64_t GetBufferCoefficient(int64_t dtypeFlag)
{
    switch (dtypeFlag) {
        case 0: case 1: return 8;    // float16 / bfloat16
        case 2:         return 12;   // float32
        case 3:         return 12;   // int32
        case 4:         return 24;   // int64
        default:        return 12;
    }
}

// Extract scalar value from 0-d tensor as double, cast appropriately per dtype
static double ExtractScalar(const at::Tensor &t)
{
    auto dtype = t.scalar_type();
    if (dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16) {
        return t.item<double>();
    } else if (dtype == at::kInt) {
        return static_cast<double>(t.item<int32_t>());
    } else if (dtype == at::kLong) {
        return static_cast<double>(t.item<int64_t>());
    }
    return t.item<double>();
}

at::Tensor arange(const at::Tensor &start, const at::Tensor &end, const at::Tensor &step)
{
    // ---- 输入校验 ----
    TORCH_CHECK(start.dim() == 0 && end.dim() == 0 && step.dim() == 0,
                "arange: start, end, step must be 0-dimensional scalar tensors");

    at::ScalarType dtype = start.scalar_type();
    TORCH_CHECK(dtype == end.scalar_type() && dtype == step.scalar_type(),
                "arange: start, end, step must have the same dtype");

    int64_t dtypeFlag = GetDtypeFlag(dtype);
    TORCH_CHECK(dtypeFlag >= 0, "arange: unsupported dtype, got ", dtype);

    // ---- 提取标量值 ----
    double startVal = ExtractScalar(start);
    double endVal = ExtractScalar(end);
    double stepVal = ExtractScalar(step);

    // ---- 计算输出长度 ----
    TORCH_CHECK(stepVal != 0.0, "arange: step must not be zero");
    // totalLength = ceil((endVal - startVal) / stepVal)
    int64_t totalLength = static_cast<int64_t>(std::ceil((endVal - startVal) / stepVal));
    if (totalLength < 0) {
        totalLength = 0;
    }

    int64_t totalLengthAligned = totalLength;
    if (totalLength == 0) {
        // Return empty tensor of correct dtype
        return at::empty({0}, at::TensorOptions().dtype(dtype).device(start.device()));
    }

    // ---- 创建输出 tensor ----
    at::Tensor output = at::empty({totalLength}, at::TensorOptions().dtype(dtype).device(start.device()));

    int64_t dtypeSize = output.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t alignNumBlock = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    if (alignNumBlock == 0) { alignNumBlock = 1; }
    int64_t totalLengthCoreAlign = (totalLengthCore + alignNumBlock - 1) / alignNumBlock * alignNumBlock;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    int64_t bufferCoefficient = GetBufferCoefficient(dtypeFlag);
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Convert scalar values to float for kernel
    float startValFloat = static_cast<float>(startVal);
    float stepValFloat = static_cast<float>(stepVal);

    EXEC_KERNEL_CMD(arange, blockDim,
                    output,
                    startValFloat, stepValFloat,
                    formerNum, formerLength, tailLength, tileLength,
                    dtypeSize, dtypeFlag);

    return output;
}

}  // namespace ascend_kernel
