#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Helper: CopyOut (UB → GM)
template <typename T>
__aicore__ inline void CopyOutHelper(const AscendC::GlobalTensor<T> &dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
class KernelArange {
public:
    __aicore__ inline KernelArange() {}

    __aicore__ inline void Init(GM_ADDR y,
                                float startVal, float stepVal,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            this->coreBaseIdx = formerLength * blockIdx;
            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreBaseIdx, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            this->coreBaseIdx = formerLength * formerNum + tailLength * tailIdx;
            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreBaseIdx, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        // For fp16/bf16: allocate FP32 temp buffer for upcast computation
        // For int32: allocate temp buffer for CreateVecIndexCalc index generation
        // For int64: no extra temp buffer needed (scalar approach)
        if constexpr (sizeof(T) == 2 || std::is_same_v<T, int32_t>) {
            pipe.InitBuffer(tempBuf, tileLength * sizeof(float));
        } else if constexpr (std::is_same_v<T, float>) {
            pipe.InitBuffer(tempBuf, tileLength * sizeof(float));
        }

        // Store start/step as appropriate types
        if constexpr (std::is_same_v<T, int32_t>) {
            this->startValInt = static_cast<int32_t>(startVal);
            this->stepValInt = static_cast<int32_t>(stepVal);
        } else if constexpr (std::is_same_v<T, int64_t>) {
            this->startValInt64 = static_cast<int64_t>(startVal);
            this->stepValInt64 = static_cast<int64_t>(stepVal);
        } else {
            this->startValFloat = startVal;
            this->stepValFloat = stepVal;
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        if (alignNum == 0) { alignNum = 1; }
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
        int32_t count = static_cast<int32_t>(curTileLength);

        // Global starting index for this tile
        int64_t globalOffset = progress * this->tileLength;

        if constexpr (std::is_same_v<T, float>) {
            // float32: Generate index sequence then compute output
            AscendC::LocalTensor<float> idxLocal = tempBuf.Get<float>();
            float tileStart = this->startValFloat + static_cast<float>(this->coreBaseIdx + globalOffset) * this->stepValFloat;
            AscendC::CreateVecIndexCalc(idxLocal, tileStart, static_cast<uint32_t>(count));
            AscendC::Muls(yLocal, idxLocal, this->stepValFloat, count);
            AscendC::Adds(yLocal, yLocal, tileStart - tileStart * this->stepValFloat, count);
        } else if constexpr (sizeof(T) == 2) {
            // float16 or bfloat16: Cast to FP32 → compute → Cast back
            AscendC::LocalTensor<float> tmpFloat = tempBuf.Get<float>();
            float tileStart = this->startValFloat + static_cast<float>(this->coreBaseIdx + globalOffset) * this->stepValFloat;
            AscendC::CreateVecIndexCalc(tmpFloat, tileStart, static_cast<uint32_t>(count));
            AscendC::Muls(tmpFloat, tmpFloat, this->stepValFloat, count);
            AscendC::Adds(tmpFloat, tmpFloat, tileStart - tileStart * this->stepValFloat, count);
            AscendC::Cast(yLocal, tmpFloat, AscendC::RoundMode::CAST_ROUND, count);
        } else if constexpr (std::is_same_v<T, int32_t>) {
            // int32: Generate index in FP32, then cast to int32
            AscendC::LocalTensor<float> tmpFloat = tempBuf.Get<float>();
            float tileStart = static_cast<float>(this->startValInt) +
                              static_cast<float>(this->coreBaseIdx + globalOffset) * static_cast<float>(this->stepValInt);
            AscendC::CreateVecIndexCalc(tmpFloat, tileStart, static_cast<uint32_t>(count));
            AscendC::Muls(tmpFloat, tmpFloat, static_cast<float>(this->stepValInt), count);
            AscendC::Adds(tmpFloat, tmpFloat, tileStart - tileStart * static_cast<float>(this->stepValInt), count);
            AscendC::Cast(yLocal, tmpFloat, AscendC::RoundMode::CAST_RINT, count);
        } else {
            // int64: Scalar approach since vector arithmetic APIs don't fully support int64
            static_assert(std::is_same_v<T, int64_t>, "Unsupported type");
            int64_t tileStart = this->startValInt64 +
                               (this->coreBaseIdx + globalOffset) * this->stepValInt64;
            for (int64_t j = 0; j < curTileLength; ++j) {
                yLocal.SetValue(static_cast<int32_t>(j), tileStart + j * this->stepValInt64);
            }
        }

        outQueueY.EnQue<T>(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
