#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Helper: CopyOut (UB → GM)
template <typename T>
__aicore__ inline void CopyOutHelper(const AscendC::GlobalTensor<T> &dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
class KernelArange {
public:
    __aicore__ inline KernelArange() {}

    __aicore__ inline void Init(GM_ADDR y,
                                float startVal, float stepVal,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            this->coreBaseIdx = formerLength * blockIdx;
            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreBaseIdx, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            this->coreBaseIdx = formerLength * formerNum + tailLength * tailIdx;
            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreBaseIdx, tailLength);
        }

        this->tileLength = tileLength;
        this->startVal = startVal;
        this->stepVal = stepVal;

        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        // Allocate FP32 temp buffer for intermediate computation
        // (used by all dtypes, even int32 which needs float to index)
        if constexpr (!std::is_same_v<T, int64_t>) {
            pipe.InitBuffer(tempBuf, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        if (alignNum == 0) { alignNum = 1; }
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    // Compute: generate arange sequence for this tile
    // output[j] = tileStart + j * step, j = 0, 1, ..., curTileLength-1
    // where tileStart = start + (coreBaseIdx + progress*tileLength) * step
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
        int32_t count = static_cast<int32_t>(curTileLength);
        int64_t globalOffset = progress * this->tileLength;
        float tileStart = this->startVal + static_cast<float>(this->coreBaseIdx + globalOffset) * this->stepVal;

        if constexpr (std::is_same_v<T, float>) {
            // float32: direct computation
            // Step 1: Create index [0, 1, 2, ..., count-1]
            AscendC::LocalTensor<float> tmpFloat = tempBuf.Get<float>();
            AscendC::CreateVecIndexCalc(tmpFloat, 0.0f, static_cast<uint32_t>(count));
            // Step 2: Multiply by step → [0, step, 2*step, ...]
            AscendC::Muls(tmpFloat, tmpFloat, this->stepVal, count);
            // Step 3: Add tileStart → [tileStart, tileStart+step, ...]
            AscendC::Adds(yLocal, tmpFloat, tileStart, count);
        } else if constexpr (sizeof(T) == 2) {
            // half or bfloat16: FP32 intermediate → Cast back
            AscendC::LocalTensor<float> tmpFloat = tempBuf.Get<float>();
            AscendC::CreateVecIndexCalc(tmpFloat, 0.0f, static_cast<uint32_t>(count));
            AscendC::Muls(tmpFloat, tmpFloat, this->stepVal, count);
            AscendC::Adds(tmpFloat, tmpFloat, tileStart, count);
            AscendC::Cast(yLocal, tmpFloat, AscendC::RoundMode::CAST_ROUND, count);
        } else if constexpr (std::is_same_v<T, int32_t>) {
            // int32: FP32 intermediate → Cast to int32 with rounding
            AscendC::LocalTensor<float> tmpFloat = tempBuf.Get<float>();
            AscendC::CreateVecIndexCalc(tmpFloat, 0.0f, static_cast<uint32_t>(count));
            AscendC::Muls(tmpFloat, tmpFloat, this->stepVal, count);
            AscendC::Adds(tmpFloat, tmpFloat, tileStart, count);
            AscendC::Cast(yLocal, tmpFloat, AscendC::RoundMode::CAST_RINT, count);
        } else {
            // int64: Scalar approach (vector arithmetic APIs don't support int64)
            static_assert(std::is_same_v<T, int64_t>, "Unsupported type");
            int64_t startInt64 = static_cast<int64_t>(this->startVal);
            int64_t stepInt64 = static_cast<int64_t>(this->stepVal);
            int64_t tileStartI64 = startInt64 +
                (this->coreBaseIdx + globalOffset) * stepInt64;
            for (int64_t j = 0; j < curTileLength; ++j) {
                yLocal.SetValue(static_cast<int32_t>(j), tileStartI64 + j * stepInt64);
            }
        }

        outQueueY.EnQue<T>(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        CopyOutHelper(yGm[progress * this->tileLength], yLocal, static_cast<uint32_t>(curTileLength));
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
    int64_t coreBaseIdx;
    float startVal;
    float stepVal;
};

// dtypeFlag: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64
extern "C" __global__ __aicore__ void arange(GM_ADDR y,
                                               float startVal, float stepVal,
                                               int64_t formerNum, int64_t formerLength,
                                               int64_t tailLength, int64_t tileLength,
                                               int64_t dtypeSize, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelArange<half> op;
        op.Init(y, startVal, stepVal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeFlag == 1) {
        KernelArange<bfloat16_t> op;
        op.Init(y, startVal, stepVal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeFlag == 2) {
        KernelArange<float> op;
        op.Init(y, startVal, stepVal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeFlag == 3) {
        KernelArange<int32_t> op;
        op.Init(y, startVal, stepVal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeFlag == 4) {
        KernelArange<int64_t> op;
        op.Init(y, startVal, stepVal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
