from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "arange_ext*")

# 优先 whl import（触发 TORCH_LIBRARY 注册）
try:
    import arange_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """AscendC optimized Arange model."""

    def __init__(self):
        super().__init__()

    def forward(self, start: torch.Tensor, end: torch.Tensor, step: torch.Tensor) -> torch.Tensor:
        """
        Generate a 1D tensor of values from start to end with given step.
        Equivalent to torch.arange(start.item(), end.item(), step.item()).

        Args:
            start: 0-d scalar tensor (start value)
            end: 0-d scalar tensor (end value, exclusive)
            step: 0-d scalar tensor (step size)

        Returns:
            1D tensor of evenly spaced values
        """
        return torch.ops.npu.arange(start, end, step)
