21	// dtypeFlag: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64
22	static int64_t GetDtypeFlag(at::ScalarType dtype)
23	{
24	    switch (dtype) {
25	        case at::kHalf:     return 0;
26	        case at::kBFloat16: return 1;
27	        case at::kFloat:    return 2;
28	        case at::kInt:      return 3;
29	        case at::kLong:     return 4;
30	        default:            return -1;
31	    }
32	}
33	
34	// bufferCoefficient: per-element UB usage in bytes
35	// float16/bf16: 8  (outQueue*2*2 + tempBuf*4 = 8 per elem)
36	// float32:      12 (outQueue*2*4 + tempBuf*4 = 12 per elem)
37	// int32:        12 (outQueue*2*4 + tempBuf*4 = 12 per elem)
38	// int64:        24 (outQueue*2*8 + tempBuf*8 = 24 per elem)
39	static int64_t GetBufferCoefficient(int64_t dtypeFlag)
40	{
41	    switch (dtypeFlag) {
42	        case 0: case 1: return 8;    // float16 / bfloat16
43	        case 2:         return 12;   // float32
44	        case 3:         return 12;   // int32
45	        case 4:         return 24;   // int64
46	        default:        return 12;
47	    }
48	}
49	
50	// Extract scalar value from 0-d tensor as double, cast appropriately per dtype
51	static double ExtractScalar(const at::Tensor &t)
52	{
53	    auto dtype = t.scalar_type();
54	    if (dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16) {
55	        return t.item<double>();
56	    } else if (dtype == at::kInt) {
57	        return static_cast<double>(t.item<int32_t>());
58	    } else if (dtype == at::kLong) {
59	        return static_cast<double>(t.item<int64_t>());
60	    }
61	    return t.item<double>();
62	}
63	
64	at::Tensor arange(const at::Tensor &start, const at::Tensor &end, const at::Tensor &step)
65	{
66	    // ---- 输入校验 ----
67	    TORCH_CHECK(start.dim() == 0 && end.dim() == 0 && step.dim() == 0,
68	                "arange: start, end, step must be 0-dimensional scalar tensors");
69	
70	    at::ScalarType dtype = start.scalar_type();
71	    TORCH_CHECK(dtype == end.scalar_type() && dtype == step.scalar_type(),
72	                "arange: start, end, step must have the same dtype");
73	
74	    int64_t dtypeFlag = GetDtypeFlag(dtype);
75	    TORCH_CHECK(dtypeFlag >= 0, "arange: unsupported dtype, got ", dtype);
76	
77	    // ---- 提取标量值 ----
78	    double startVal = ExtractScalar(start);
79	    double endVal = ExtractScalar(end);
80	    double stepVal = ExtractScalar(step);
81	
82	    // ---- 计算输出长度 ----
83	    TORCH_CHECK(stepVal != 0.0, "arange: step must not be zero");
84	    // totalLength = ceil((endVal - startVal) / stepVal)
85	    int64_t totalLength = static_cast<int64_t>(std::ceil((endVal - startVal) / stepVal));
86	    if (totalLength < 0) {
87	        totalLength = 0;
88	    }
89	
90	    int64_t totalLengthAligned = totalLength;
91	    if (totalLength == 0) {
92	        // Return empty tensor of correct dtype
93	        return at::empty({0}, at::TensorOptions().dtype(dtype).device(start.device()));
94	    }
95	
96	    // ---- 创建输出 tensor ----
97	    at::Tensor output = at::empty({totalLength}, at::TensorOptions().dtype(dtype).device(start.device()));
98	
99	    int64_t dtypeSize = output.element_size();
100	
101	    // ---- 获取硬件参数 ----
102	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
103	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
104	    uint64_t ubSize;
105	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
106	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
107	
108	    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
109	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
110	    int64_t alignNumBlock = CACHE_LINE_BYTE_LENGTH / dtypeSize;
111	    if (alignNumBlock == 0) { alignNumBlock = 1; }
112	    int64_t totalLengthCoreAlign = (totalLengthCore + alignNumBlock - 1) / alignNumBlock * alignNumBlock;
113	
114	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
115	    int64_t formerNum = usedCoreNum - 1;
116	    int64_t formerLength = totalLengthCoreAlign;
117	    int64_t tailLength = totalLength - formerNum * formerLength;
118	
119	    // ---- UB 级 tiling (核内切分) ----
120	    int64_t bufferCoefficient = GetBufferCoefficient(dtypeFlag);
121	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
122	    if (dtypeSize == 0) { dtypeSize = 1; }
123	    int64_t alignElements = 32 / dtypeSize;
124	    if (alignElements == 0) { alignElements = 1; }
125	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
126	
127	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
128	
129	    // Convert scalar values to float for kernel
130	    float startValFloat = static_cast<float>(startVal);
131	    float stepValFloat = static_cast<float>(stepVal);
132	
133	    EXEC_KERNEL_CMD(arange, blockDim,
134	                    output,
135	                    startValFloat, stepValFloat,
136	                    formerNum, formerLength, tailLength, tileLength,
137	                    dtypeSize, dtypeFlag);
138	
139	    return output;
140	}
